:root {
  --bg: #fdf8f5;
  --hero-gradient: linear-gradient(135deg, #fde8ee, #ede8fc, #fdf5f0);
  --surface-rose: #fef0f5;
  --surface-lavender: #f3f0fd;
  --surface-matcha: #f0f7f0;
  --surface-peach: #fdf5f0;
  --rose: #f4b8c8;
  --rose-dark: #c97a90;
  --lavender: #c8b8f0;
  --lavender-dark: #9a7ad4;
  --peach: #f8c8a8;
  --peach-dark: #c07040;
  --matcha: #b8ddb8;
  --matcha-dark: #7ab87a;
  --text: #5a3a4a;
  --text-muted: #b09898;
  --progress-gradient: linear-gradient(90deg, #f4b8c8, #c8b8f0, #f8c8a8);
  --nav-active: #c97a90;
  --radius: 14px;
  --radius-sm: 8px;
  --radius-full: 999px;
}

html, body {
  height: 100%;
  overflow-x: hidden;
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

#root {
  height: 100%;
  max-width: 430px;
  margin: 0 auto;
  position: relative;
}

h1, h2, h3, .serif {
  font-family: 'Playfair Display', Georgia, serif;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

input, select, textarea {
  font-family: inherit;
}

img {
  max-width: 100%;
}

.page {
  min-height: 100dvh;
  padding-bottom: 80px;
  background: var(--bg);
  overflow-y: auto;
}

.scrollable {
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

::-webkit-scrollbar { display: none; }

