import BottomNav from '../components/BottomNav'
import styles from './Scan.module.css'

const client = new Anthropic({
  apiKey: import.meta.env.VITE_ANTHROPIC_API_KEY,
  dangerouslyAllowBrowser: true,
})

const MEAL_TIMES = ['breakfast', 'lunch', 'dinner', 'snack']
const MOODS = ['😊 Great', '😐 Okay', '😴 Tired', '💪 Energized', '😩 Sluggish']

export default function Scan() {
  const { dietaryPreference, addDiaryEntry } = useUser()
  const [image, setImage] = useState(null)
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState(null)
  const [error, setError] = useState(null)
  const [mealTime, setMealTime] = useState(guessCurrentMeal())
  const [mood, setMood] = useState('')
  const [added, setAdded] = useState(false)
  const fileRef = useRef()
  const cameraRef = useRef()

  function guessCurrentMeal() {
    const h = new Date().getHours()
    if (h < 10) return 'breakfast'
    if (h < 14) return 'lunch'
    if (h < 18) return 'snack'
    return 'dinner'
  }

  function handleFile(e) {
    const file = e.target.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onload = ev => {
      setImage(ev.target.result)
      setResult(null)
      setError(null)
      setAdded(false)
      analyzeImage(ev.target.result)
    }
    reader.readAsDataURL(file)
  }

  async function analyzeImage(dataUrl) {
    setLoading(true)
    setError(null)
    try {
      if (!import.meta.env.VITE_ANTHROPIC_API_KEY) {
        setResult(getMockResult())
        setLoading(false)
        return
      }

      const base64 = dataUrl.split(',')[1]
      const mediaType = dataUrl.split(';')[0].split(':')[1]

      const msg = await client.messages.create({
        model: 'claude-sonnet-4-20250514',
        max_tokens: 600,
        messages: [{
          role: 'user',
          content: [
            {
              type: 'image',
              source: { type: 'base64', media_type: mediaType, data: base64 }
            },
            {
              type: 'text',
              text: `Analyze this food image. Respond ONLY with a JSON object, no markdown:
{
  "name": "food name",
  "kcal": number,
  "protein": number (grams),
  "carbs": number (grams),
  "fat": number (grams),
  "confidence": number (0-100),
  "isVeg": boolean,
  "alternative": "healthier ${dietaryPreference === 'veg' ? 'vegetarian ' : ''}alternative suggestion"
}
Estimate for a standard serving. If multiple items, sum them up.`
            }
          ]
        }]
      })

      const text = msg.content[0].text.trim()
      const json = JSON.parse(text)
      const score = scoreMeal(json)
      setResult({ ...json, score })
    } catch (e) {
      setError('Could not analyze the image. Please try again.')
      console.error(e)
    } finally {
      setLoading(false)
    }
  }

  function getMockResult() {
    return {
      name: 'Mixed grain bowl', kcal: 420, protein: 18, carbs: 55, fat: 12,
      confidence: 87, isVeg: true, score: 8,
      alternative: dietaryPreference === 'veg'
        ? 'Try adding edamame for more protein'
        : 'Add grilled chicken for extra protein'
    }
  }

  function addToDiary() {
    if (!result) return
    addDiaryEntry({
      name: result.name,
      kcal: result.kcal,
      protein: result.protein,
      carbs: result.carbs,
      fat: result.fat,
      score: result.score,
      isVeg: result.isVeg ?? isVegKeyword(result.name),
      mealTime,
      mood: mood.split(' ')[1] || '',
    })
    setAdded(true)
  }

  return (
    <div className={`page ${styles.scan}`}>
      <div className={styles.header}>
        <h1 className={styles.title}>Snap a meal</h1>
        <p className={styles.sub}>Point at food to get instant nutrition</p>
      </div>

      {/* Viewfinder */}
      <div className={styles.viewfinder} onClick={() => !image && fileRef.current.click()}>
        {image ? (
          <img src={image} alt="food" className={styles.preview} />
        ) : (
          <div className={styles.placeholder}>
            <div className={styles.corner} />
            <CameraIcon />
            <p className={styles.placeholderText}>Tap to take / upload a photo</p>
          </div>
        )}
        {loading && (
          <motion.div className={styles.loader}
            animate={{ opacity: [0.5, 1, 0.5] }}
            transition={{ duration: 1.2, repeat: Infinity }}>
            <div className={styles.pulse} />
            <span>Analyzing with AI...</span>
          </motion.div>
        )}
      </div>

      <div className={styles.actions}>
        <button className={styles.uploadBtn} onClick={() => fileRef.current.click()}>
          Upload photo
        </button>
        <button className={styles.cameraBtn} onClick={() => cameraRef.current.click()}>
          Camera
        </button>
      </div>

      <input ref={fileRef} type="file" accept="image/*" hidden onChange={handleFile} />
      <input ref={cameraRef} type="file" accept="image/*" capture="environment" hidden onChange={handleFile} />

      {error && <p className={styles.error}>{error}</p>}

      {/* Result card */}
      <AnimatePresence>
        {result && !loading && (
          <motion.div className={styles.result}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0 }}
            transition={{ duration: 0.4 }}>

            <div className={styles.resultHeader}>
              <span className={styles.vegDot} style={{ background: result.isVeg ? 'var(--matcha-dark)' : 'var(--rose-dark)' }} />
              <h2 className={styles.foodName}>{result.name}</h2>
              <ScoreBadge score={result.score} />
            </div>

            <div className={styles.macroRow}>
              <div className={styles.macroChip} style={{ background: 'var(--surface-rose)', color: 'var(--rose-dark)' }}>
                <span className={styles.macroVal}>{result.kcal}</span>
                <span className={styles.macroLbl}>kcal</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-rose)', color: 'var(--rose-dark)' }}>
                <span className={styles.macroVal}>{result.protein}g</span>
                <span className={styles.macroLbl}>protein</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-lavender)', color: 'var(--lavender-dark)' }}>
                <span className={styles.macroVal}>{result.carbs}g</span>
                <span className={styles.macroLbl}>carbs</span>
              </div>
              <div className={styles.macroChip} style={{ background: 'var(--surface-peach)', color: 'var(--peach-dark)' }}>
                <span className={styles.macroVal}>{result.fat}g</span>
                <span className={styles.macroLbl}>fat</span>
              </div>
            </div>

            <div className={styles.confidence}>
              Confidence: <strong>{result.confidence}%</strong>
            </div>

            {result.alternative && (
              <div className={styles.altCard}>
                <span className={styles.altLabel}>Healthier alternative</span>
                <p className={styles.altText}>{result.alternative}</p>
              </div>
            )}

            {/* Meal time selector */}
            <div className={styles.timeRow}>
              {MEAL_TIMES.map(t => (
                <button
                  key={t}
                  className={`${styles.timeChip} ${mealTime === t ? styles.timeActive : ''}`}
                  onClick={() => setMealTime(t)}>
                  {t}
                </button>
              ))}
            </div>

            {/* Mood tag */}
            <div className={styles.moodRow}>
              <span className={styles.moodLabel}>How do you feel?</span>
              <div className={styles.moodChips}>
                {MOODS.map(m => (
                  <button
                    key={m}
                    className={`${styles.moodChip} ${mood === m ? styles.moodActive : ''}`}
                    onClick={() => setMood(m === mood ? '' : m)}>
                    {m}
                  </button>
                ))}
              </div>
            </div>

            {added ? (
              <div className={styles.addedMsg}>Added to diary ✓</div>
            ) : (
              <button className={styles.addBtn} onClick={addToDiary}>
                Add to Diary
              </button>
            )}
          </motion.div>
        )}
      </AnimatePresence>

      <BottomNav />
    </div>
  )
}

function CameraIcon() {
  return (
    <svg width="48" height="48" viewBox="0 0 24 24" fill="none" opacity="0.4">
      <path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z" stroke="#c97a90" strokeWidth="1.5" fill="none" strokeLinejoin="round" />
      <circle cx="12" cy="13" r="4" stroke="#c97a90" strokeWidth="1.5" />
    </svg>
  )
}

import { useState } from 'react'
import { useUser } from '../context/UserContext'
import { useStreak } from '../hooks/useStreak'
import FlowerIcon from '../assets/FlowerIcon'
import BottomNav from '../components/BottomNav'
import styles from './Profile.module.css'

const GOALS_LABEL = { lose: 'Lose weight', maintain: 'Maintain', gain: 'Gain muscle' }

export default function Profile() {
  const { name, photo, calorieGoal, dietaryPreference, fitnessGoal, waterGoal, notifications, update } = useUser()
  const { streak, milestones, nextMilestone, daysToNext, milestoneEmoji } = useStreak()
  const [editing, setEditing] = useState(false)
  const [draft, setDraft] = useState({ name, calorieGoal, waterGoal })

  function saveEdits() {
    update(draft)
    setEditing(false)
  }

  function togglePref() {
    update({ dietaryPreference: dietaryPreference === 'veg' ? 'non-veg' : 'veg' })
  }

  // Build last 30 days streak calendar
  const calendarDays = Array.from({ length: 30 }).map((_, i) => {
    const d = new Date()
    d.setDate(d.getDate() - (29 - i))
    return { date: d.toISOString().slice(0, 10), label: d.getDate() }
  })

  return (
    <div className={`page ${styles.profile}`}>
      <div className={styles.header}>
        <div className={styles.photoWrap}>
          {photo
            ? <img src={photo} alt={name} className={styles.photo} />
            : <div className={styles.photoFallback}><FlowerIcon size={36} color="#c97a90" /></div>
          }
        </div>

        {editing ? (
          <div className={styles.editBlock}>
            <input
              className={styles.nameInput}
              value={draft.name}
              onChange={e => setDraft(d => ({ ...d, name: e.target.value }))}
              placeholder="Your name"
            />
            <div className={styles.editRow}>
              <label className={styles.editLabel}>Calorie goal</label>
              <input
                type="number"
                className={styles.numInput}
                value={draft.calorieGoal}
                onChange={e => setDraft(d => ({ ...d, calorieGoal: Number(e.target.value) }))}
              />
            </div>
            <div className={styles.editRow}>
              <label className={styles.editLabel}>Water goal (glasses)</label>
              <input
                type="number"
                className={styles.numInput}
                value={draft.waterGoal || 8}
                onChange={e => setDraft(d => ({ ...d, waterGoal: Number(e.target.value) }))}
              />
            </div>
            <div className={styles.editActions}>
              <button className={styles.cancelBtn} onClick={() => setEditing(false)}>Cancel</button>
              <button className={styles.saveBtn} onClick={saveEdits}>Save</button>
            </div>
          </div>
        ) : (
          <div className={styles.info}>
            <h2 className={styles.name}>{name || 'Your name'}</h2>
            <p className={styles.goal}>{calorieGoal} kcal/day · {GOALS_LABEL[fitnessGoal]}</p>
            <button className={styles.editBtn} onClick={() => setEditing(true)}>Edit profile</button>
          </div>
        )}
      </div>

      {/* Streak */}
      <div className={styles.streakCard}>
        <div className={styles.streakTop}>
          <FlowerIcon size={20} color="#c97a90" />
          <span className={styles.streakTitle}><em>{streak}</em> day glow streak</span>
        </div>
        <p className={styles.streakSub}>
          {daysToNext === 0
            ? `${milestoneEmoji(nextMilestone)} You hit the ${nextMilestone}-day milestone!`
            : `${daysToNext} days to ${nextMilestone}-day milestone ${milestoneEmoji(nextMilestone)}`}
        </p>
        <div className={styles.milestones}>
          {[3, 7, 14, 30].map(m => (
            <div key={m} className={`${styles.milestone} ${milestones.includes(m) ? styles.milestoneAchieved : ''}`}>
              <span>{milestoneEmoji(m)}</span>
              <span>{m}d</span>
            </div>
          ))}
        </div>
      </div>

      {/* Dietary preference toggle */}
      <div className={styles.settingsCard}>
        <h3 className={styles.settingsTitle}>Diet preference</h3>
        <div className={styles.toggleRow}>
          <button
            className={`${styles.prefBtn} ${dietaryPreference === 'veg' ? styles.prefActive : ''}`}
            onClick={() => update({ dietaryPreference: 'veg' })}>
            <span className={styles.dot} style={{ background: 'var(--matcha-dark)' }} />
            Vegetarian
          </button>
          <button
            className={`${styles.prefBtn} ${dietaryPreference === 'non-veg' ? styles.prefActive : ''}`}
            onClick={() => update({ dietaryPreference: 'non-veg' })}>
            <span className={styles.dot} style={{ background: 'var(--rose-dark)' }} />
            Non-Vegetarian
          </button>
        </div>
        <p className={styles.prefNote}>
          {dietaryPreference === 'veg'
            ? 'AI suggestions will show vegetarian options only'
            : 'AI suggestions show all food options'}
        </p>
      </div>

      {/* Settings */}
      <div className={styles.settingsCard}>
        <h3 className={styles.settingsTitle}>Settings</h3>
        <div className={styles.settingRow}>
          <span className={styles.settingLabel}>Notifications</span>
          <button
            className={`${styles.toggle} ${notifications ? styles.toggleOn : ''}`}
            onClick={() => update({ notifications: !notifications })}>
            <div className={styles.toggleThumb} />
          </button>
        </div>
      </div>

      {/* Streak calendar */}
      <div className={styles.settingsCard}>
        <h3 className={styles.settingsTitle}>Streak calendar</h3>
        <div className={styles.calendar}>
          {calendarDays.map((d, i) => {
            const isToday = d.date === new Date().toISOString().slice(0, 10)
            // We can't easily know past activity without more state — highlight last `streak` days
            const streakStart = new Date()
            streakStart.setDate(streakStart.getDate() - streak + 1)
            const isActive = new Date(d.date) >= streakStart
            return (
              <div
                key={i}
                className={`${styles.calDay} ${isActive ? styles.calActive : ''} ${isToday ? styles.calToday : ''}`}
                title={d.date}>
                {d.label}
              </div>
            )
          })}
        </div>
      </div>

      <BottomNav />
    </div>
  )
}

