function BlobBg() {
  return (
    <div style={{
      position: 'fixed', inset: 0, zIndex: 0,
      pointerEvents: 'none', overflow: 'hidden'
    }}>
      {/* Outer corner blobs */}
      <div style={{ position: 'absolute', width: 260, height: 260, top: -100, left: -80, borderRadius: '50%', background: '#e0789a', opacity: 0.4, filter: 'blur(35px)' }} />
      <div style={{ position: 'absolute', width: 220, height: 220, top: -80, right: -80, borderRadius: '50%', background: '#a87ad4', opacity: 0.32, filter: 'blur(35px)' }} />
      <div style={{ position: 'absolute', width: 200, height: 200, bottom: -70, left: -60, borderRadius: '50%', background: '#4a9a4a', opacity: 0.28, filter: 'blur(35px)' }} />
      <div style={{ position: 'absolute', width: 240, height: 240, bottom: -90, right: -80, borderRadius: '50%', background: '#e09060', opacity: 0.35, filter: 'blur(35px)' }} />
      {/* Inner blobs */}
      <div style={{ position: 'absolute', width: 180, height: 180, top: '8%', right: '-5%', borderRadius: '50%', background: '#e0789a', opacity: 0.18, filter: 'blur(28px)' }} />
      <div style={{ position: 'absolute', width: 160, height: 160, top: '42%', left: '-5%', borderRadius: '50%', background: '#a87ad4', opacity: 0.18, filter: 'blur(28px)' }} />
      <div style={{ position: 'absolute', width: 160, height: 160, bottom: '18%', right: '-5%', borderRadius: '50%', background: '#4a9a4a', opacity: 0.18, filter: 'blur(28px)' }} />
    </div>
  )
}

function AppRoutes() {
  const { onboardingDone } = useUser()

  if (!onboardingDone) {
    return (
      <Routes>
        <Route path="*" element={<Onboarding />} />
      </Routes>
    )
  }

  return (
    <Routes>
      <Route path="/"         element={<Navigate to="/home" replace />} />
      <Route path="/home"     element={<Home />} />
      <Route path="/scan"     element={<Scan />} />
      <Route path="/diary"    element={<Diary />} />
      <Route path="/progress" element={<Progress />} />
      <Route path="/profile"  element={<Profile />} />
      <Route path="*"         element={<Navigate to="/home" replace />} />
    </Routes>
  )
}

export default function App() {
  return (
    <BrowserRouter>
      <UserProvider>
        <BlobBg />
        <AppRoutes />
      </UserProvider>
    </BrowserRouter>
  )
}

