.profile { padding: 0 20px 90px; }
.header {
  padding-top: 32px;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 20px;
}
.photoWrap { flex-shrink: 0; }
.photo {
  width: 80px; height: 80px;
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid var(--rose);
}
.photoFallback {
  width: 80px; height: 80px;
  border-radius: 50%;
  background: var(--surface-rose);
  border: 3px solid var(--rose);
  display: flex;
  align-items: center;
  justify-content: center;
}
.info { flex: 1; }
.name {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 22px;
  font-style: italic;
  color: var(--text);
}
.goal { font-size: 13px; color: var(--text-muted); margin-top: 4px; }
.editBtn {
  margin-top: 8px;
  font-size: 12px;
  color: var(--rose-text);
  background: var(--surface-rose);
  border: 1.5px solid var(--rose-dark);
  border-radius: 999px;
  padding: 4px 12px;
  cursor: pointer;
}
.editBlock { flex: 1; display: flex; flex-direction: column; gap: 10px; }
.nameInput {
  width: 100%;
  padding: 10px 12px;
  border: 1.5px solid var(--rose-dark);
  border-radius: var(--radius-sm);
  font-size: 15px;
  background: var(--surface-rose);
  color: var(--text);
  outline: none;
}
.editRow { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.editLabel { font-size: 13px; color: var(--text-muted); }
.numInput {
  width: 80px;
  padding: 6px 10px;
  border: 1.5px solid var(--peach-dark);
  border-radius: var(--radius-sm);
  font-size: 14px;
  text-align: center;
  background: var(--surface-peach);
  color: var(--text);
  outline: none;
  -moz-appearance: textfield;
}
.numInput::-webkit-outer-spin-button,
.numInput::-webkit-inner-spin-button { -webkit-appearance: none; }
.editActions { display: flex; gap: 8px; }
.cancelBtn {
  padding: 8px 16px;
  border-radius: 999px;
  border: 1.5px solid var(--rose-dark);
  color: var(--rose-text);
  font-size: 13px;
  cursor: pointer;
}
.saveBtn {
  flex: 1;
  padding: 8px;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--rose-dark), var(--lavender-dark));
  color: white;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

.streakCard {
  background: linear-gradient(135deg, #fad4e0, #e4d8f8);
  border: 1.5px solid #e8a0b8;
  border-radius: var(--radius);
  padding: 18px;
  margin-bottom: 16px;
}
.streakTop { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.streakTitle {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 17px;
  color: var(--rose-text);
}
.streakTitle em { font-style: italic; }
.streakSub { font-size: 13px; color: var(--text-muted); margin-bottom: 14px; }
.milestones { display: flex; gap: 8px; }
.milestone {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 8px 4px;
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.45);
  font-size: 12px;
  color: var(--text-muted);
