.preview { width: 100%; height: 100%; object-fit: cover; }
.loader {
  position: absolute;
  inset: 0;
  background: rgba(253,232,238,0.85);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  font-size: 14px;
  color: var(--rose-dark);
  font-style: italic;
}
.pulse {
  width: 48px; height: 48px;
  border-radius: 50%;
  background: radial-gradient(circle, var(--rose), var(--lavender));
  animation: pulse 1.2s ease-in-out infinite;
}
@keyframes pulse {
  0%, 100% { transform: scale(0.8); opacity: 0.6; }
  50% { transform: scale(1.1); opacity: 1; }
}

.actions {
  display: flex;
  gap: 10px;
  margin-top: 14px;
}
.uploadBtn, .cameraBtn {
  flex: 1;
  padding: 12px;
  border-radius: var(--radius-full);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.uploadBtn {
  background: var(--surface-rose);
  border: 1.5px solid var(--rose);
  color: var(--rose-dark);
}
.cameraBtn {
  background: linear-gradient(135deg, var(--rose), var(--lavender-dark));
  color: white;
  border: none;
}

.error {
  margin-top: 10px;
  font-size: 13px;
  color: var(--rose-dark);
  text-align: center;
}

.result {
  margin-top: 20px;
  background: var(--surface-rose);
  border: 1px solid var(--rose);
  border-radius: var(--radius);
  padding: 18px;
}
.resultHeader {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}
.vegDot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }
.foodName {
  flex: 1;
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 18px;
  font-style: italic;
  color: var(--text);
}
.macroRow {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 10px;
}
.macroChip {
  flex: 1;
  min-width: 60px;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 4px;
  border-radius: var(--radius-sm);
}
.macroVal {
  font-family: 'Playfair Display', Georgia, serif;
  font-size: 18px;
  font-style: italic;
  font-weight: 600;
}
.macroLbl { font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; margin-top: 2px; opacity: 0.7; }
.confidence { font-size: 12px; color: var(--text-muted); margin-bottom: 12px; }
.altCard {
  background: var(--surface-matcha);
  border: 1px solid var(--matcha);
  border-radius: var(--radius-sm);
  padding: 10px 12px;
  margin-bottom: 14px;
}
.altLabel { font-size: 11px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--matcha-dark); font-weight: 600; }
.altText { font-size: 13px; color: var(--text); margin-top: 4px; }
.timeRow {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}
.timeChip {
  padding: 5px 12px;
  border-radius: 999px;
  font-size: 12px;
  background: white;
  border: 1.5px solid #f0e0e8;
  color: var(--text-muted);
  cursor: pointer;
  text-transform: capitalize;
  transition: all 0.2s;
}
.timeActive {
  background: var(--surface-lavender);
  border-color: var(--lavender);
  color: var(--lavender-dark);
  font-weight: 600;
}
.moodRow { margin-bottom: 16px; }
.moodLabel { font-size: 12px; color: var(--text-muted); margin-bottom: 8px; display: block; }
.moodChips { display: flex; gap: 6px; flex-wrap: wrap; }
.moodChip {
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 12px;
  background: white;
  border: 1.5px solid #f0e0e8;
  color: var(--text);
  cursor: pointer;
  transition: all 0.2s;
}
.moodActive {
  background: var(--surface-peach);
  border-color: var(--peach);
  color: var(--peach-dark);
}
.addBtn {
  width: 100%;
