import { useState } from 'react'
import ScoreBadge from './ScoreBadge'
import styles from './MealCard.module.css'

const MEAL_COLORS = {
  breakfast: { bg: 'var(--surface-peach)', border: '#e8b070' },
  lunch:     { bg: 'var(--surface-rose)',  border: '#e890a8' },
  dinner:    { bg: 'var(--surface-lavender)', border: '#b098d8' },
  snack:     { bg: 'var(--surface-matcha)', border: '#80b878' },
}

export default function MealCard({ entry, onDelete }) {
  const cfg = MEAL_COLORS[entry.mealTime] || MEAL_COLORS.snack
  const [expanded, setExpanded] = useState(false)
  const hasItems = Array.isArray(entry.items) && entry.items.length > 0

  return (
    <div className={styles.card} style={{ background: cfg.bg, borderLeft: `3px solid ${cfg.border}` }}>
      <div className={styles.top}>
        <div className={styles.nameRow}>
          <span className={styles.dot} style={{ background: entry.isVeg ? 'var(--matcha-dark)' : 'var(--rose-dark)' }} />
          <span className={styles.name}>{entry.name}</span>
          {entry.score && <ScoreBadge score={entry.score} />}
          {hasItems && (
            <button
              className={styles.expandBtn}
              onClick={() => setExpanded(e => !e)}
              aria-label={expanded ? 'Collapse items' : 'Expand items'}
            >
              {expanded ? '▾' : '▸'}
            </button>
          )}
        </div>
        <span className={styles.kcal}>{entry.kcal} kcal</span>
      </div>

      <div className={styles.macros}>
        <span className={styles.macro} style={{ background: 'rgba(255,255,255,0.6)', color: 'var(--rose-text)' }}>P {entry.protein}g</span>
        <span className={styles.macro} style={{ background: 'rgba(255,255,255,0.6)', color: 'var(--lavender-text)' }}>C {entry.carbs}g</span>
        <span className={styles.macro} style={{ background: 'rgba(255,255,255,0.6)', color: 'var(--peach-text)' }}>F {entry.fat}g</span>
        {entry.mood && <span className={styles.tag}>{entry.mood}</span>}
        {hasItems && (
          <span className={styles.itemCount}>{entry.items.length} items</span>
        )}
      </div>

      {/* Collapsible items */}
      {hasItems && expanded && (
        <div className={styles.itemsList}>
          {entry.items.map((item, i) => (
            <div key={i} className={styles.subItem}>
              <div className={styles.subLeft}>
                <span
                  className={styles.subDot}
                  style={{ background: item.isVeg ? 'var(--matcha-dark)' : 'var(--rose-dark)' }}
                />
                <span className={styles.subName}>{item.name}</span>
                {item.quantity && (
                  <span className={styles.subQty}>· {item.quantity}</span>
                )}
              </div>
              <span className={styles.subKcal}>{item.kcal} kcal</span>
            </div>
          ))}
        </div>
      )}

      {onDelete && (
        <button className={styles.del} onClick={() => onDelete(entry.id)} aria-label="Delete entry">
          ×
        </button>
      )}
    </div>
  )
}

.card {
  border-radius: var(--radius);
  padding: 12px 14px;
  position: relative;
  margin-bottom: 8px;
}
.top {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 6px;
}
.nameRow {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 1;
  flex-wrap: wrap;
}
.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}
.name {
  font-size: 14px;
  font-weight: 500;
  color: var(--text);
  font-style: italic;
  font-family: 'Playfair Display', Georgia, serif;
}
.kcal {
  font-size: 13px;
  font-weight: 600;
  color: var(--rose-text);
  white-space: nowrap;
  margin-left: 8px;
}
.macros {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
  align-items: center;
}
.macro {
  font-size: 11px;
  font-weight: 600;
  padding: 1px 7px;
  border-radius: 999px;
}
.tag {
  font-size: 11px;
  color: var(--text-muted);
  padding: 1px 6px;
  border-radius: 999px;
  background: rgba(255,255,255,0.5);
}
.itemCount {
  font-size: 10px;
  color: var(--text-muted);
  padding: 1px 6px;
  border-radius: 999px;
  background: rgba(255,255,255,0.5);
  font-weight: 500;
}
.expandBtn {
  background: none;
  border: none;
  color: var(--text-muted);
  font-size: 11px;
  cursor: pointer;
  padding: 0 2px;
  line-height: 1;
  flex-shrink: 0;
  transition: color 0.15s;
}
.expandBtn:hover { color: var(--rose-dark); }

/* ── Collapsible sub-items ── */
.itemsList {
  margin-top: 8px;
  padding-top: 7px;
  border-top: 1px solid rgba(0,0,0,0.07);
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.subItem {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 4px 8px;
  border-left: 2.5px solid var(--rose-dark);
  border-radius: 0 6px 6px 0;
  background: rgba(255,255,255,0.45);
  margin-left: 4px;
}
.subLeft {
  display: flex;
  align-items: center;
  gap: 5px;
  flex: 1;
  min-width: 0;
}
.subDot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
}
.subName {
  font-size: 12px;
  color: var(--text);
  font-weight: 500;
}
.subQty {
  font-size: 11px;
  color: var(--text-muted);
  flex-shrink: 0;
}
.subKcal {
  font-size: 11px;
  font-weight: 600;
  color: var(--rose-text);
  white-space: nowrap;
  margin-left: 8px;
  flex-shrink: 0;
}

.del {
  position: absolute;
  top: 8px;
  right: 10px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: rgba(255,255,255,0.7);
  color: var(--text-muted);
  font-size: 16px;
  display: flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: background 0.2s;
}
.del:hover { background: var(--surface-rose); color: var(--rose-text); }

